def block(id,element='div',html=None,cls='',children=None,attrs=None):
    b={'blockId':'cg-'+id,'blockName':id.replace('-',' ').title(),'element':element,'baseStyles':{},'mobileStyles':{},'tabletStyles':{},'attributes':attrs or {},'classes':cls.split(),'children':children or []}
    if html is not None:b['innerHTML']=html
    return b

def sectionheading(eyebrow,title,href,label):
    return f'<div><p class="cg-eyebrow">{eyebrow}</p><h2>{title}</h2></div><a class="cg-link" href="{href}">{label} {arrow}</a>'

