pages=[('callus_all_products','callus-all-products','all-products','store','Shop plants & garden essentials'),('landing_page','landing-page','shop','home','Plants, pots & little joys'),('all_products','all-products','store','store','Shop plants & garden essentials'),('categories','categories','categories','categories','Shop by category'),('category','category','category/:name','category','Discover your kind of green'),('collections','collections','collections','collections','Thoughtful collections'),('collection','collection','collection/:name','collection','The Callus edit'),('products_details','products-details','item/:item_code','product','Product details'),('cart','cart','cart','basket','Your basket'),('callus_checkout','callus-checkout','checkout','checkout','Guest checkout'),('callus_saved','callus-saved','saved','saved','Your saved favourites'),('callus_contact','callus-contact','contact-callus','contact','Visit & contact Callus'),('callus_delivery','callus-delivery','delivery-and-returns','delivery','Delivery & product help'),('callus_account','callus-account','account-callus','account','My account'),('callus_privacy','callus-privacy','privacy-callus','privacy','Privacy & cookies')]

def build():
    for kind,extension in [('css','css'),('js','js')]:
        name='callus-storefront-'+kind;folder=DEST/'client_scripts'/name.replace('-','_');folder.mkdir(parents=True,exist_ok=True)
        (folder/(name.replace('-','_')+'.json')).write_text(json.dumps({'doctype':'Builder Client Script','modified':RELEASE['modified'],'name':name,'script_type':{'css':'CSS','js':'JavaScript'}[kind],'script':(APP/'public/callus'/('storefront.'+extension)).read_text()},indent=1)+'\n')
    data_script=(APP/'callus_storefront/data_script.py').read_text()
    for directory,name,route,kind,title in pages:
        folder=DEST/'pages'/directory;folder.mkdir(parents=True,exist_ok=True)
        content=home if kind=='home' else [block(kind+'-content',html={'contact':contact,'delivery':delivery,'account':account,'privacy':privacy}.get(kind,'<div class="cg-wrap cg-section"><p>Loading your next favourite…</p><noscript>Please enable JavaScript to browse the catalogue, or call +356 9999 5135.</noscript></div>'))]
        root=block('root','body',cls='cg-app',attrs={'data-page':kind},children=[block('header',html=header),block('main','main',children=content,attrs={'id':'cg-main'}),block('footer',html=footer),block('catalogue-data','script',html='{{ catalogue | tojson }}',attrs={'id':'cg-catalogue','type':'application/json'})])
        root['blockId']='root'
        doc={'doctype':'Builder Page','modified':RELEASE['modified'],'name':name,'page_name':name,'page_title':title,'route':route,'published':1,'is_standard':1,'app':'webshop','project_folder':'webshop','authenticated_access':0,'dynamic_route':int(':' in route),'page_data_script':data_script,'disable_indexing':0,'blocks':[root],'head_html':'<meta name="theme-color" content="#244c3a"><meta name="color-scheme" content="light">','body_html':'','meta_description':'Discover plants, pots, garden essentials and thoughtful gifts at Callus Garden Centre in Siġġiewi, Malta.','client_scripts':[{'builder_script':'callus-storefront-css'},{'builder_script':'callus-storefront-js'}]}
        (folder/(directory+'.json')).write_text(json.dumps(doc,indent=1,ensure_ascii=False)+'\n')
        (folder/'data_script.py').write_text(data_script)
    print('Built',len(pages),'Builder pages and 2 shared scripts.')
if __name__=='__main__':build()
